                vol.Optional(
                    CONF_ENABLE_CLIMATE,
                    default=current_enable_climate,
                ): bool,
                vol.Optional(
                    CONF_ENABLE_SELECT,
                    default=current_enable_select,
                ): bool,
            }
        ),
    )

